        TavernCampaignWorld_Broadcast(self, StringConcat(StringConcat(StringConcat(StringConcat(StringConcat("    [Action] ", self->journey.cleric.name), " "), WeaponCard_ActionLine(clericWeapon, clericStrategy)), " at "), CombatTarget(stateId, round, 1)));
        TavernCampaignWorld_Broadcast(self, StringConcat("    [Effect] ", WeaponCard_EffectLine(clericWeapon, clericStrategy)));
        TavernCampaignWorld_Broadcast(self, StringConcat(StringConcat(StringConcat(StringConcat(StringConcat("    [Action] ", self->journey.rogue.name), " "), WeaponCard_ActionLine(rogueWeapon, rogueStrategy)), " against "), CombatTarget(stateId, round, 2)));
        TavernCampaignWorld_Broadcast(self, StringConcat("    [Effect] ", WeaponCard_EffectLine(rogueWeapon, rogueStrategy)));
        TavernCampaignWorld_Broadcast(self, StringConcat(StringConcat(StringConcat(StringConcat(StringConcat("    [Action] ", self->journey.mage.name), " "), WeaponCard_ActionLine(mageWeapon, mageStrategy)), " through "), CombatTarget(stateId, round, 3)));
        TavernCampaignWorld_Broadcast(self, StringConcat("    [Effect] ", WeaponCard_EffectLine(mageWeapon, mageStrategy)));
        TavernCampaignWorld_ResolveSkirmishSeat(self, stateId, 0, option, pulse);
        TavernCampaignWorld_ResolveSkirmishSeat(self, stateId, 1, option, pulse);
        TavernCampaignWorld_ResolveSkirmishSeat(self, stateId, 2, option, pulse);
        TavernCampaignWorld_ResolveSkirmishSeat(self, stateId, 3, option, pulse);
        if (((pulse % 2) == 0))
        {
            Adventurer_BondEvent(&self->journey.rogue, 1, 1);
        }
        if ((pulse >= 3))
        {
            Adventurer_DrinkPotion(&self->journey.cleric, (2 + pulse));
        }
        if ((stateId == 3))
        {
            self->journey.keyCount = (self->journey.keyCount + 1);
        }
        self->journey.threat = (((self->journey.threat - 1)) > (0) ? ((self->journey.threat - 1)) : (0));
        self->journey.trapLevel = (((self->journey.trapLevel - 1)) > (0) ? ((self->journey.trapLevel - 1)) : (0));
        self->journey.treasure = ((self->journey.treasure + pulse) + (stateId - 1));
        TavernCampaignWorld_Broadcast(self, StringConcat("    [Resolve] Ari ", TavernCampaignWorld_MemberShortState(self, 0)));
        TavernCampaignWorld_Broadcast(self, StringConcat("    [Resolve] Mira ", TavernCampaignWorld_MemberShortState(self, 1)));
        TavernCampaignWorld_Broadcast(self, StringConcat("    [Resolve] Nyx ", TavernCampaignWorld_MemberShortState(self, 2)));
